macro.sample.deck:
var n = deck.AddSlide();
deck.SetTitle(n, "Resumen");
deck.SetBody(n, "Diapositivas: " + deck.SlideCount);
app.Log(deck.Title(n));

macro.sample.folio:
var n = doc.AppendParagraph("Resumen");
doc.SetStyle(n, "Heading 1");
doc.AppendParagraph("Palabras: " + doc.WordCount);
app.Log(doc.Paragraph(n));
